contracts/ClawTrustAC.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./interfaces/IERC8183.sol";
import "./interfaces/IClawTrustContracts.sol";

/**
 * @title ClawTrustAC
 * @author ClawTrust
 * @notice ERC-8183 Agentic Commerce adapter for ClawTrust.
 *
 * This contract exposes a standard ERC-8183 interface for external protocols
 * and AI agent frameworks. It wraps ClawTrust's identity and reputation layer
 * without modifying any existing production contracts.
 *
 * CRITICAL: All existing production contracts are READ-ONLY from this adapter.
 * Custody of USDC for ERC-8183 jobs is held by this contract directly.
 *
 * Production Contracts (Base Sepolia — DO NOT REDEPLOY):
 *   ClawCardNFT:            0xf24e41980ed48576Eb379D2116C1AaD075B342C4
 *   ClawTrustRepAdapter:    0xecc00bbE268Fa4D0330180e0fB445f64d824d818
 *   ClawTrustBond:          0x23a1E1e958C932639906d0650A13283f6E60132c
 *   USDC (Base Sepolia):    0x036CbD53842c5426634e7929541eC2318f3dCF7e
 */
contract ClawTrustAC is IERC8183, Ownable2Step, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ═══════════════════════════════════════════════════════════
    // PRODUCTION CONTRACT REFERENCES (READ-ONLY)
    // ═══════════════════════════════════════════════════════════

    IClawCardNFT public immutable clawCard;
    IClawTrustRepAdapter public immutable repAdapter;
    IClawTrustBond public immutable bond;
    IERC20 public immutable usdc;

    // ═══════════════════════════════════════════════════════════
    // CONSTANTS
    // ═══════════════════════════════════════════════════════════

    uint256 public constant PLATFORM_FEE_BPS = 250;
    uint256 public constant BPS_DENOMINATOR = 10_000;
    uint256 public constant MIN_BUDGET = 1e4;
    uint256 public constant MIN_DURATION = 1 hours;
    uint256 public constant MAX_DURATION = 90 days;
    uint256 public constant DISPUTE_WINDOW = 48 hours;

    // ═══════════════════════════════════════════════════════════
    // STATE
    // ═══════════════════════════════════════════════════════════

    struct Job {
        address client;
        address provider;
        address evaluator;
        uint256 budget;
        uint256 expiredAt;
        JobStatus status;
        string description;
        bytes32 deliverableHash;
        bytes32 outcomeReason;
        uint256 createdAt;
    }

    mapping(bytes32 => Job) public jobs;
    mapping(bytes32 => uint256) public submittedAt;
    uint256 private _jobCounter;

    address public treasury;
    address public evaluator;
    uint256 public evaluatorThreshold;

    uint256 public totalJobsCreated;
    uint256 public totalJobsCompleted;
    uint256 public totalVolumeUSDC;

    // ═══════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════

    error JobNotFound();
    error InvalidStatus();
    error Unauthorized();
    error InvalidAmount();
    error InvalidAddress();
    error InvalidDuration();
    error JobNotExpired();
    error JobAlreadyExpired();
    error ProviderNotRegistered();
    error SelfDealingNotAllowed();

    // ═══════════════════════════════════════════════════════════
    // ADDITIONAL EVENTS
    // ═══════════════════════════════════════════════════════════

    event EvaluatorUpdated(address indexed oldEvaluator, address indexed newEvaluator);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event FeesCollected(bytes32 indexed jobId, uint256 amount);

    // ═══════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════

    constructor(
        address _clawCard,
        address _repAdapter,
        address _bond,
        address _usdc,
        address _treasury,
        address _evaluator
    ) Ownable(msg.sender) {
        if (_clawCard == address(0) || _repAdapter == address(0) || _bond == address(0) ||
            _usdc == address(0) || _treasury == address(0) || _evaluator == address(0))
            revert InvalidAddress();

        clawCard = IClawCardNFT(_clawCard);
        repAdapter = IClawTrustRepAdapter(_repAdapter);
        bond = IClawTrustBond(_bond);
        usdc = IERC20(_usdc);
        treasury = _treasury;
        evaluator = _evaluator;
        uint256 evaluatorCount = (_evaluator == msg.sender) ? 1 : 2;
        evaluatorThreshold = (evaluatorCount >= 2) ? 2 : 1;
    }

    // ═══════════════════════════════════════════════════════════
    // ERC-8183 INTERFACE IMPLEMENTATION
    // ═══════════════════════════════════════════════════════════

    /**
     * @notice Create a new job. Anyone can post a job.
     * @param description Human-readable description of the work
     * @param budget USDC amount (6 decimals) to be paid on completion
     * @param durationSeconds How long providers have to complete the work
     * @return jobId The bytes32 job identifier
     */
    function createJob(
        string calldata description,
        uint256 budget,
        uint256 durationSeconds
    ) external override whenNotPaused returns (bytes32 jobId) {
        if (budget < MIN_BUDGET) revert InvalidAmount();
        if (durationSeconds < MIN_DURATION || durationSeconds > MAX_DURATION) revert InvalidDuration();
        if (bytes(description).length > 1000) revert InvalidAmount();

        _jobCounter++;
        // abi.encode (not encodePacked) prevents hash-collision between different-length inputs
        jobId = keccak256(abi.encode(msg.sender, _jobCounter, block.timestamp));

        uint256 expiry = block.timestamp + durationSeconds;

        jobs[jobId] = Job({
            client: msg.sender,
            provider: address(0),
            evaluator: evaluator,
            budget: budget,
            expiredAt: expiry,
            status: JobStatus.Open,
            description: description,
            deliverableHash: bytes32(0),
            outcomeReason: bytes32(0),
            createdAt: block.timestamp
        });

        totalJobsCreated++;

        emit JobCreated(jobId, msg.sender, budget, expiry);
    }

    /**
     * @notice Fund a job by transferring USDC into this contract.
     * @dev Client must approve this contract for `budget` USDC before calling.
     * @param jobId The job to fund
     */
    // slither-disable-next-line reentrancy-no-eth
    // Protected by `nonReentrant`. safeTransferFrom is on the trusted USDC token.
    // State update (job.status = Funded) happens after the transfer — CEI is intentionally
    // inverted here because the transfer must succeed before we mark the job as funded.
    function fund(bytes32 jobId) external override nonReentrant whenNotPaused {
        Job storage job = jobs[jobId];
        if (job.client == address(0)) revert JobNotFound();
        if (job.status != JobStatus.Open) revert InvalidStatus();
        if (msg.sender != job.client) revert Unauthorized();
        if (block.timestamp >= job.expiredAt) revert JobAlreadyExpired();

        usdc.safeTransferFrom(msg.sender, address(this), job.budget);
        job.status = JobStatus.Funded;

        emit JobFunded(jobId, msg.sender, job.budget);
    }

    /**
     * @notice Assign a provider to a funded job. Only the client can assign.
     * @dev Provider must hold a ClawCard NFT (ERC-8004 registered agent).
     * @param jobId The job to assign
     * @param provider The agent wallet address to assign
     */
    function assignProvider(bytes32 jobId, address provider) external override whenNotPaused {
        if (provider == address(0)) revert InvalidAddress();
        Job storage job = jobs[jobId];
        if (job.client == address(0)) revert JobNotFound();
        if (job.status != JobStatus.Funded) revert InvalidStatus();
        if (msg.sender != job.client) revert Unauthorized();
        if (provider == job.client) revert SelfDealingNotAllowed();
        if (block.timestamp >= job.expiredAt) revert JobAlreadyExpired();

        if (!clawCard.isRegistered(provider)) revert ProviderNotRegistered();

        job.provider = provider;
        job.status = JobStatus.Assigned;

        emit JobProviderAssigned(jobId, provider);
    }

    /**
     * @notice Provider submits completed work. Triggers the evaluation phase.
     * @param jobId The job being submitted
     * @param deliverableHash Hash of the deliverable (IPFS CID, proof URL hash, etc.)
     */
    function submit(bytes32 jobId, bytes32 deliverableHash) external override whenNotPaused {
        Job storage job = jobs[jobId];
        if (job.client == address(0)) revert JobNotFound();
        if (job.status != JobStatus.Assigned) revert InvalidStatus();
        if (msg.sender != job.provider) revert Unauthorized();
        if (block.timestamp >= job.expiredAt) revert JobAlreadyExpired();

        job.deliverableHash = deliverableHash;
        job.status = JobStatus.Submitted;
        submittedAt[jobId] = block.timestamp;

        emit JobSubmitted(jobId, msg.sender, deliverableHash);
    }

    /**
     * @notice Mark a submitted job as completed. Releases USDC to provider.
     * @dev Only the evaluator (oracle) can call this. Platform fee deducted.
     * @param jobId The job to complete
     * @param reason bytes32 attestation reason (e.g. keccak of "SWARM_APPROVED")
     */
    function complete(bytes32 jobId, bytes32 reason) external override nonReentrant whenNotPaused {
        if (msg.sender != evaluator && msg.sender != owner()) revert Unauthorized();

        Job storage job = jobs[jobId];
        if (job.client == address(0)) revert JobNotFound();
        if (job.status != JobStatus.Submitted) revert InvalidStatus();

        _executeCompletion(jobId, reason, job);
    }

    /**
     * @notice Public fallback: anyone can finalize a submitted job
     *         after DISPUTE_WINDOW (48h) if evaluators are unresponsive.
     *         Bypasses evaluator threshold — provider protection mechanism.
     */
    function completeAfterTimeout(bytes32 jobId, bytes32 reason)
        external nonReentrant whenNotPaused {
        Job storage job = jobs[jobId];
        if (job.client == address(0)) revert JobNotFound();
        if (job.status != JobStatus.Submitted) revert InvalidStatus();
        if (block.timestamp < submittedAt[jobId] + DISPUTE_WINDOW) {
            revert Unauthorized();
        }
        _executeCompletion(jobId, reason, job);
    }

    // slither-disable-next-line reentrancy-benign
    // Protected by `nonReentrant` on all callers. State is updated before safeTransfer payouts.
    // Any re-entry from USDC token callbacks is blocked by the mutex. Slither reports benign
    // because the written vars (job.status, job.outcomeReason) are not re-readable externally.
    function _executeCompletion(bytes32 jobId, bytes32 reason, Job storage job) internal {
        job.status = JobStatus.Completed;
        job.outcomeReason = reason;

        uint256 fee = (job.budget * PLATFORM_FEE_BPS) / BPS_DENOMINATOR;
        uint256 payout = job.budget - fee;

        if (fee > 0) {
            usdc.safeTransfer(treasury, fee);
            emit FeesCollected(jobId, fee);
        }
        usdc.safeTransfer(job.provider, payout);

        totalJobsCompleted++;
        totalVolumeUSDC += job.budget;

        emit JobCompleted(jobId, job.provider, reason);
    }

    /**
     * @notice Mark a submitted job as rejected. Refunds USDC to client.
     * @dev Only the evaluator (oracle) can call this.
     * @param jobId The job to reject
     * @param reason bytes32 attestation reason (e.g. keccak of "SWARM_REJECTED")
     */
    function reject(bytes32 jobId, bytes32 reason) external override nonReentrant whenNotPaused {
        if (msg.sender != evaluator && msg.sender != owner()) revert Unauthorized();

        Job storage job = jobs[jobId];
        if (job.client == address(0)) revert JobNotFound();
        if (job.status != JobStatus.Submitted) revert InvalidStatus();

        job.status = JobStatus.Rejected;
        job.outcomeReason = reason;

        usdc.safeTransfer(job.client, job.budget);

        emit JobRejected(jobId, job.client, reason);
    }

    /**
     * @notice Cancel a job. Client can cancel if Open or Funded (before submission).
     *         Refunds USDC to client if already funded.
     * @param jobId The job to cancel
     */
    function cancel(bytes32 jobId) external override nonReentrant whenNotPaused {
        Job storage job = jobs[jobId];
        if (job.client == address(0)) revert JobNotFound();
        if (msg.sender != job.client && msg.sender != owner()) revert Unauthorized();
        if (job.status != JobStatus.Open && job.status != JobStatus.Funded) revert InvalidStatus();

        bool wasFunded = (job.status == JobStatus.Funded);
        job.status = JobStatus.Cancelled;

        if (wasFunded) {
            usdc.safeTransfer(job.client, job.budget);
        }

        emit JobCancelled(jobId, job.client);
    }

    /**
     * @notice Expire a job that has passed its deadline. Refunds USDC to client.
     * @dev Anyone can call this to clean up expired funded jobs.
     * @param jobId The job to expire
     */
    function expireJob(bytes32 jobId) external override nonReentrant {
        Job storage job = jobs[jobId];
        if (job.client == address(0)) revert JobNotFound();
        if (block.timestamp < job.expiredAt) revert JobNotExpired();
        if (job.status != JobStatus.Open && job.status != JobStatus.Funded && job.status != JobStatus.Assigned && job.status != JobStatus.Submitted)
            revert InvalidStatus();

        bool hadFunds = job.status == JobStatus.Funded || job.status == JobStatus.Assigned || job.status == JobStatus.Submitted;
        job.status = JobStatus.Expired;

        if (hadFunds) {
            usdc.safeTransfer(job.client, job.budget);
        }

        emit JobExpired(jobId);
    }

    /**
     * @notice Get the current status of a job.
     * @param jobId The job to query
     * @return Current JobStatus enum value
     */
    function getJobStatus(bytes32 jobId) external view override returns (JobStatus) {
        Job storage job = jobs[jobId];
        if (job.client == address(0)) revert JobNotFound();
        return job.status;
    }

    // ═══════════════════════════════════════════════════════════
    // READ FUNCTIONS
    // ═══════════════════════════════════════════════════════════

    /**
     * @notice Get full job details.
     */
    function getJob(bytes32 jobId) external view returns (Job memory) {
        if (jobs[jobId].client == address(0)) revert JobNotFound();
        return jobs[jobId];
    }

    /**
     * @notice Get the total number of jobs ever created.
     */
    function jobCount() external view returns (uint256) {
        return _jobCounter;
    }

    /**
     * @notice Check ERC-8004 registration status of a provider wallet.
     */
    function isRegisteredAgent(address wallet) external view returns (bool) {
        return clawCard.isRegistered(wallet);
    }

    /**
     * @notice Get stats for the ERC-8183 adapter.
     */
    function getStats() external view returns (
        uint256 created,
        uint256 completed,
        uint256 volumeUSDC,
        uint256 completionRate
    ) {
        created = totalJobsCreated;
        completed = totalJobsCompleted;
        volumeUSDC = totalVolumeUSDC;
        completionRate = created > 0 ? (completed * 100) / created : 0;
    }

    // ═══════════════════════════════════════════════════════════
    // ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════

    function setEvaluator(address _evaluator) external onlyOwner {
        if (_evaluator == address(0)) revert InvalidAddress();
        emit EvaluatorUpdated(evaluator, _evaluator);
        evaluator = _evaluator;
    }

    function setTreasury(address _treasury) external onlyOwner {
        if (_treasury == address(0)) revert InvalidAddress();
        emit TreasuryUpdated(treasury, _treasury);
        treasury = _treasury;
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function emergencyWithdraw(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        if (to == address(0)) revert InvalidAddress();
        if (token == address(usdc)) revert Unauthorized();
        IERC20(token).safeTransfer(to, amount);
    }

    function recoverStuckUSDC(address to) external onlyOwner nonReentrant {
        if (to == address(0)) revert InvalidAddress();
        uint256 balance = usdc.balanceOf(address(this));
        usdc.safeTransfer(to, balance);
    }
}

contracts/ClawTrustSwarmValidator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract ClawTrustSwarmValidator is Ownable2Step, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    enum VoteType { None, Approve, Reject }
    enum ValidationStatus { Pending, Approved, Rejected, Expired }

    struct ValidationRequest {
        bytes32 gigId;
        address poster;
        address assignee;
        address[] candidates;
        mapping(address => VoteType) votes;
        mapping(address => bool) isCandidate;
        uint256 votesFor;
        uint256 votesAgainst;
        uint256 threshold;
        ValidationStatus status;
        uint256 createdAt;
        uint256 resolvedAt;
        uint256 expiresAt;
        uint256 rewardPool;
        uint256 rewardPoolClaimed;
        address rewardToken;
        address escrowSnapshot;
        address rewardRefundTarget;
        mapping(address => bool) rewardClaimed;
    }

    struct ValidationInfo {
        bytes32 gigId;
        address poster;
        address assignee;
        address[] candidates;
        uint256 votesFor;
        uint256 votesAgainst;
        uint256 threshold;
        ValidationStatus status;
        uint256 createdAt;
        uint256 resolvedAt;
        uint256 expiresAt;
        uint256 rewardPool;
        address rewardToken;
    }

    mapping(bytes32 => ValidationRequest) internal validations;
    mapping(bytes32 => bool) public validationExists;

    address public escrowContract;
    uint256 public constant MAX_CANDIDATES = 50;
    uint256 public constant VALIDATION_DURATION = 7 days;
    uint256 public constant SWEEP_CLAIM_WINDOW = 14 days;
    uint256 public defaultThreshold = 3;
    uint256 public defaultCandidateCount = 5;

    event ValidationCreated(
        bytes32 indexed gigId,
        address indexed assignee,
        address[] candidates,
        uint256 threshold,
        uint256 rewardPool,
        address rewardToken,
        uint256 expiresAt
    );
    event VoteCast(bytes32 indexed gigId, address indexed voter, VoteType vote);
    event ValidationResolved(
        bytes32 indexed gigId,
        ValidationStatus status,
        uint256 votesFor,
        uint256 votesAgainst
    );
    event RewardClaimed(bytes32 indexed gigId, address indexed validator, uint256 amount);
    event ResidualRewardSwept(bytes32 indexed gigId, address indexed to, uint256 amount);
    event ValidationExpired(bytes32 indexed gigId);
    event EscrowContractUpdated(address indexed oldEscrow, address indexed newEscrow);
    event DefaultThresholdUpdated(uint256 oldThreshold, uint256 newThreshold);

    error ValidationAlreadyExists();
    error InsufficientCandidates();
    error InvalidThreshold();
    error ValidationNotFound();
    error ValidationAlreadyResolved();
    error InvalidVote();
    error AlreadyVoted();
    error NotCandidate();
    error TooManyCandidates();
    error DuplicateCandidate();
    error InvalidAddress();
    error NoRewardAvailable();
    error RewardAlreadyClaimed();
    error InsufficientRewardPool();
    error ValidationNotApproved();
    error TransferFailed();
    error NotExpired();
    error AssigneeCannotValidate();
    error PosterCannotValidate();

    modifier onlyEscrowOrOwner() {
        if(msg.sender != escrowContract && msg.sender != owner()) revert InvalidAddress();
        _;
    }

    constructor(address _escrowContract) Ownable(msg.sender) {
        if(_escrowContract == address(0)) revert InvalidAddress();
        escrowContract = _escrowContract;
    }

    // slither-disable-next-line reentrancy-no-eth
    // nonReentrant guards the safeTransferFrom call on the rewardToken (which could be any ERC-20).
    // Although onlyEscrowOrOwner restricts callers to trusted addresses, a malicious rewardToken
    // with an on-transfer callback could re-enter without the guard. nonReentrant closes this.
    function createValidation(
        bytes32 gigId,
        address poster,
        address assignee,
        address[] calldata candidates,
        uint256 threshold,
        uint256 rewardPool,
        address rewardToken
    ) external nonReentrant onlyEscrowOrOwner whenNotPaused {
        if(validationExists[gigId]) revert ValidationAlreadyExists();
        if(poster == address(0)) revert InvalidAddress();
        if(candidates.length > MAX_CANDIDATES) revert TooManyCandidates();
        if(candidates.length < threshold) revert InsufficientCandidates();
        if(threshold == 0) revert InvalidThreshold();
        if(rewardToken == address(0)) revert InvalidAddress();

        if(rewardPool > 0) {
            IERC20(rewardToken).safeTransferFrom(msg.sender, address(this), rewardPool);
        }

        ValidationRequest storage v = validations[gigId];
        v.gigId = gigId;
        v.poster = poster;
        v.assignee = assignee;
        v.threshold = threshold;
        v.status = ValidationStatus.Pending;
        v.createdAt = block.timestamp;
        v.expiresAt = block.timestamp + VALIDATION_DURATION;
        v.rewardPool = rewardPool;
        v.rewardToken = rewardToken;
        v.escrowSnapshot = escrowContract;
        v.rewardRefundTarget = poster;

        for (uint256 i = 0; i < candidates.length; i++) {
            address candidate = candidates[i];
            if(candidate == address(0)) revert InvalidAddress();
            if(v.isCandidate[candidate]) revert DuplicateCandidate();
            if(candidate == assignee) revert AssigneeCannotValidate();
            if(candidate == poster) revert PosterCannotValidate();

            v.candidates.push(candidate);
            v.isCandidate[candidate] = true;
        }

        validationExists[gigId] = true;

        emit ValidationCreated(gigId, assignee, candidates, threshold, rewardPool, rewardToken, v.expiresAt);
    }

    function vote(bytes32 gigId, VoteType _vote) external nonReentrant whenNotPaused {
        if(!validationExists[gigId]) revert ValidationNotFound();
        ValidationRequest storage v = validations[gigId];

        if(v.status != ValidationStatus.Pending) revert ValidationAlreadyResolved();
        if(block.timestamp >= v.expiresAt) {
            revert ValidationAlreadyResolved();
        }
        if(_vote != VoteType.Approve && _vote != VoteType.Reject) revert InvalidVote();
        if(v.votes[msg.sender] != VoteType.None) revert AlreadyVoted();
        if(!v.isCandidate[msg.sender]) revert NotCandidate();
        if(msg.sender == v.assignee) revert AssigneeCannotValidate();
        if(msg.sender == v.poster) revert PosterCannotValidate();

        v.votes[msg.sender] = _vote;

        if (_vote == VoteType.Approve) {
            v.votesFor++;
        } else {
            v.votesAgainst++;
        }

        emit VoteCast(gigId, msg.sender, _vote);

        _checkThreshold(gigId);
    }

    function _checkThreshold(bytes32 gigId) internal {
        ValidationRequest storage v = validations[gigId];
        if (v.status != ValidationStatus.Pending) return;
        if (v.votesFor >= v.threshold) {
            v.status = ValidationStatus.Approved;
            v.resolvedAt = block.timestamp;
            emit ValidationResolved(gigId, ValidationStatus.Approved, v.votesFor, v.votesAgainst);
        } else if (v.votesAgainst >= v.threshold) {
            v.status = ValidationStatus.Rejected;
            v.resolvedAt = block.timestamp;
            emit ValidationResolved(gigId, ValidationStatus.Rejected, v.votesFor, v.votesAgainst);
            _refundRewardPool(gigId);
        }
    }

    function _expireValidation(bytes32 gigId) internal {
        ValidationRequest storage v = validations[gigId];
        v.status = ValidationStatus.Expired;
        v.resolvedAt = block.timestamp;
        emit ValidationExpired(gigId);
        _refundRewardPool(gigId);
    }

    function expireValidation(bytes32 gigId) external {
        if(!validationExists[gigId]) revert ValidationNotFound();
        ValidationRequest storage v = validations[gigId];
        if(v.status != ValidationStatus.Pending) revert ValidationAlreadyResolved();
        if(block.timestamp < v.expiresAt) revert NotExpired();

        _expireValidation(gigId);
    }

    function _refundRewardPool(bytes32 gigId) internal {
        ValidationRequest storage v = validations[gigId];
        if(v.rewardPool == 0) return;

        uint256 amount = v.rewardPool - v.rewardPoolClaimed;
        if(amount == 0) return;
        v.rewardPoolClaimed = v.rewardPool;

        address target = v.rewardRefundTarget != address(0) ? v.rewardRefundTarget : v.escrowSnapshot;
        IERC20(v.rewardToken).safeTransfer(target, amount);
    }

    function claimReward(bytes32 gigId) external nonReentrant {
        if(!validationExists[gigId]) revert ValidationNotFound();
        ValidationRequest storage v = validations[gigId];

        if(v.status != ValidationStatus.Approved) revert ValidationNotApproved();
        if(v.votes[msg.sender] != VoteType.Approve) revert NoRewardAvailable();
        if(v.rewardClaimed[msg.sender]) revert RewardAlreadyClaimed();
        if(v.rewardPool == 0 || v.votesFor == 0) revert NoRewardAvailable();

        uint256 rewardPerValidator = v.rewardPool / v.votesFor;
        if(rewardPerValidator == 0) revert NoRewardAvailable();

        uint256 remaining = v.rewardPool - v.rewardPoolClaimed;
        if(remaining == 0) revert NoRewardAvailable();
        if(rewardPerValidator > remaining) {
            rewardPerValidator = remaining;
        }

        v.rewardClaimed[msg.sender] = true;
        v.rewardPoolClaimed += rewardPerValidator;

        IERC20(v.rewardToken).safeTransfer(msg.sender, rewardPerValidator);

        emit RewardClaimed(gigId, msg.sender, rewardPerValidator);
    }

    function aggregateVotes(bytes32 gigId) external view returns (
        uint256 votesFor,
        uint256 votesAgainst,
        uint256 threshold,
        uint8 status,
        bool isApproved
    ) {
        if(!validationExists[gigId]) revert ValidationNotFound();
        ValidationRequest storage v = validations[gigId];
        return (
            v.votesFor,
            v.votesAgainst,
            v.threshold,
            uint8(v.status),
            v.status == ValidationStatus.Approved
        );
    }

    function getValidationInfo(bytes32 gigId) external view returns (ValidationInfo memory) {
        if(!validationExists[gigId]) revert ValidationNotFound();
        ValidationRequest storage v = validations[gigId];
        return ValidationInfo({
            gigId: v.gigId,
            poster: v.poster,
            assignee: v.assignee,
            candidates: v.candidates,
            votesFor: v.votesFor,
            votesAgainst: v.votesAgainst,
            threshold: v.threshold,
            status: v.status,
            createdAt: v.createdAt,
            resolvedAt: v.resolvedAt,
            expiresAt: v.expiresAt,
            rewardPool: v.rewardPool,
            rewardToken: v.rewardToken
        });
    }

    function hasVoted(bytes32 gigId, address voter) external view returns (bool) {
        if(!validationExists[gigId]) revert ValidationNotFound();
        return validations[gigId].votes[voter] != VoteType.None;
    }

    function getVote(bytes32 gigId, address voter) external view returns (VoteType) {
        if(!validationExists[gigId]) revert ValidationNotFound();
        return validations[gigId].votes[voter];
    }

    function isCandidate(bytes32 gigId, address addr) external view returns (bool) {
        if(!validationExists[gigId]) revert ValidationNotFound();
        return validations[gigId].isCandidate[addr];
    }

    function setDefaultThreshold(uint256 _threshold) external onlyOwner {
        if(_threshold == 0 || _threshold > 20) revert InvalidThreshold();
        uint256 oldThreshold = defaultThreshold;
        defaultThreshold = _threshold;
        emit DefaultThresholdUpdated(oldThreshold, _threshold);
    }

    function setDefaultCandidateCount(uint256 _count) external onlyOwner {
        if(_count < 3 || _count > MAX_CANDIDATES) revert InvalidThreshold();
        defaultCandidateCount = _count;
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function setEscrowContract(address _escrow) external onlyOwner {
        if(_escrow == address(0)) revert InvalidAddress();
        address oldEscrow = escrowContract;
        escrowContract = _escrow;
        emit EscrowContractUpdated(oldEscrow, _escrow);
    }

    error SweepTooEarly();

    function sweepResidualRewards(bytes32 gigId, address to) external onlyOwner nonReentrant {
        if(!validationExists[gigId]) revert ValidationNotFound();
        if(to == address(0)) revert InvalidAddress();
        ValidationRequest storage v = validations[gigId];
        if(v.status != ValidationStatus.Approved) revert ValidationNotApproved();
        if(block.timestamp < v.resolvedAt + SWEEP_CLAIM_WINDOW) revert SweepTooEarly();

        uint256 residual = v.rewardPool - v.rewardPoolClaimed;
        if(residual == 0) revert NoRewardAvailable();

        v.rewardPoolClaimed += residual;

        IERC20(v.rewardToken).safeTransfer(to, residual);

        emit ResidualRewardSwept(gigId, to, residual);
    }

    function computeRewardPool(uint256 gigBudget, uint256 rewardRate, uint256 denominator) external pure returns (uint256) {
        return (gigBudget * rewardRate) / denominator;
    }

    function getGigVerdict(bytes32 gigId) external view returns (string memory) {
        if (!validationExists[gigId]) return "not_found";
        ValidationStatus s = validations[gigId].status;
        // slither-disable-next-line incorrect-equality -- enum switch-dispatch; == on a closed enum set is safe and intentional
        if (s == ValidationStatus.Approved) return "approved"; // solhint-disable-line
        // slither-disable-next-line incorrect-equality -- enum switch-dispatch (continued)
        if (s == ValidationStatus.Rejected) return "rejected"; // solhint-disable-line
        // slither-disable-next-line incorrect-equality -- enum switch-dispatch (continued)
        if (s == ValidationStatus.Expired)  return "expired";  // solhint-disable-line
        return "pending";
    }
}

